SELECT o.*, ub.nickname AS booster_nickname
FROM orders o
LEFT JOIN users ub ON o.booster_id = ub.id
WHERE o.customer_id = #{customerId}
ORDER BY o.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT o.*, u.nickname AS customer_nickname FROM orders o JOIN users u ON o.customer_id = u.id WHERE o.status = 'pending'
AND o.game = #{game}
ORDER BY o.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT o.*, u.nickname AS customer_nickname
FROM orders o
JOIN users u ON o.customer_id = u.id
WHERE o.booster_id = #{boosterId}
ORDER BY o.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT o.*, u.nickname AS customer_nickname, ub.nickname AS booster_nickname
FROM orders o
JOIN users u ON o.customer_id = u.id
LEFT JOIN users ub ON o.booster_id = ub.id


        AND o.status = #{status}


        AND o.game = #{game}


ORDER BY o.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT count(*) FROM orders


        AND status = #{status}


        AND game = #{game}
